events.onValueChange:
function(form) {
  if (form.get('Del_Outcome').getValue() === 'Delivered in AMRIT') {
    form.get('Del_Delivery_Date').setHidden(false);
    form.get('Global_Location_Visit').setHidden(false);
    form.get('Del_complications_in_delivery').setHidden(false);
    form.get('Del_Outcome_Delivery').setHidden(false);
    form.get('Del_N_born_sex').setHidden(false);
    form.get('Del_Type_of_Birth').setHidden(false);
    form.get('Del_LowBirth_Weight').setHidden(false);
    form.get('Del_ANY_Newborn_Compli').setHidden(false);
    form.get('Del_specify_reason').setHidden(true);
  } else {

  }
  if (form.get('Del_Outcome').getValue() === 'Referred Before Delivery') {
    form.get('Del_Delivery_Date').setHidden(true);
    form.get('Global_Location_Visit').setHidden(true);
    form.get('Del_complications_in_delivery').setHidden(false);
    form.get('Del_Outcome_Delivery').setHidden(true);
    form.get('Del_N_born_sex').setHidden(true);
    form.get('Del_Type_of_Birth').setHidden(true);
    form.get('Del_LowBirth_Weight').setHidden(true);
    form.get('Del_ANY_Newborn_Compli').setHidden(true);
    form.get('Del_specify_reason').setHidden(false);
  } else {


  }
  if (form.get('Del_Outcome').getValue() === 'LAMA') {
    form.get('Del_Delivery_Date').setHidden(true);
    form.get('Global_Location_Visit').setHidden(true);
    form.get('Del_complications_in_delivery').setHidden(true);
    form.get('Del_Outcome_Delivery').setHidden(true);
    form.get('Del_N_born_sex').setHidden(true);
    form.get('Del_Type_of_Birth').setHidden(true);
    form.get('Del_LowBirth_Weight').setHidden(true);
    form.get('Del_ANY_Newborn_Compli').setHidden(true);
    form.get('Del_specify_reason').setHidden(true);

  } else {

  }
  if (form.get('Del_Outcome').getValue() === 'False Labour') {
    form.get('Del_Delivery_Date').setHidden(true);
    form.get('Global_Location_Visit').setHidden(true);
    form.get('Del_complications_in_delivery').setHidden(true);
    form.get('Del_Outcome_Delivery').setHidden(true);
    form.get('Del_N_born_sex').setHidden(true);
    form.get('Del_Type_of_Birth').setHidden(true);
    form.get('Del_LowBirth_Weight').setHidden(true);
    form.get('Del_ANY_Newborn_Compli').setHidden(true);
    form.get('Del_specify_reason').setHidden(true);

  } else {

  }
}
